// BLOCO 5 — Portfólio e Primeiros Passos no Mercado (Artigos 25-30)
export const block5Articles: MarketTrailArticle[] = [
  {
    id: 'mt-portfolio-that-impresses',
    slugPt: 'portfolio-que-impressiona',
    slugEn: 'portfolio-that-actually-impresses',
    title: { pt: 'Como Montar um Portfólio Que Realmente Chama Atenção', en: 'How to Build a Portfolio That Actually Impresses' },
    excerpt: { pt: 'Estratégias para construir um portfólio de desenvolvimento que demonstre valor real e não apenas quantidade de repositórios.', en: 'Strategies to build a development portfolio that demonstrates real value, not just repository count.' },
    date: { pt: '19 de Fevereiro, 2026', en: 'February 19, 2026' }, publishedDate: '2026-02-19', readTime: '22 min',
    tags: { pt: ['Portfólio', 'Carreira', 'Posicionamento'], en: ['Portfolio', 'Career', 'Positioning'] },
    keywords: { pt: ['portfólio desenvolvedor', 'portfólio programação', 'projetos portfólio', 'posicionamento profissional'], en: ['developer portfolio', 'programming portfolio', 'portfolio projects', 'professional positioning'] },
    sections: [
      { title: { pt: 'Introdução: O portfólio como ferramenta de comunicação profissional', en: 'Introduction: The portfolio as a professional communication tool' }, content: { pt: 'Um portfólio não é uma coleção de repositórios no GitHub. É uma demonstração estruturada de competência, raciocínio e capacidade de entrega. A maioria dos desenvolvedores iniciantes comete o erro de tratar o portfólio como um arquivo de exercícios, quando na realidade ele deveria funcionar como uma carta de apresentação técnica que comunica: "eu sei identificar problemas, planejar soluções e executar com qualidade."\n\nO mercado de tecnologia recebe milhares de candidatos diariamente. A diferença entre ser notado ou ignorado frequentemente está na qualidade da apresentação, não na quantidade de projetos. Este artigo abre o Bloco 5 da trilha, dedicado à construção de presença profissional. Os blocos anteriores construíram fundamentos conceituais, metodológicos, técnicos e comportamentais. Agora o foco é transformar todo esse conhecimento em evidência visível e verificável de competência.', en: 'A portfolio is not a collection of GitHub repositories. It is a structured demonstration of competence, reasoning, and delivery capability. Most beginner developers make the mistake of treating the portfolio as an exercise archive, when in reality it should function as a technical cover letter that communicates: "I can identify problems, plan solutions, and execute with quality."\n\nThe technology market receives thousands of candidates daily. The difference between being noticed or ignored is often in the quality of presentation, not the quantity of projects. This article opens Block 5 of the trail, dedicated to building professional presence. The previous blocks built conceptual, methodological, technical, and behavioral fundamentals. Now the focus is transforming all that knowledge into visible and verifiable evidence of competence.' } },
      { title: { pt: 'Base conceitual: Portfólio como prova de competência', en: 'Conceptual foundation: Portfolio as proof of competence' }, content: { pt: 'O conceito de portfólio vem das artes visuais e da arquitetura, onde profissionais apresentam trabalhos anteriores para demonstrar capacidade. No desenvolvimento de software, o princípio é idêntico: mostrar o que você já construiu como evidência do que pode construir. A diferença é que código sem contexto não comunica quase nada. Um repositório com arquivos soltos, sem README, sem documentação e sem explicação do problema que resolve é invisível para recrutadores e gestores técnicos.\n\nO portfólio resolve um problema central: a assimetria de informação entre candidato e empregador. O empregador não sabe se você é competente; o portfólio reduz essa incerteza ao fornecer evidências concretas. Por isso, a qualidade da apresentação importa tanto quanto a qualidade do código. Um projeto mediano bem documentado comunica mais do que um projeto excelente sem contexto. O impacto prático é direto: portfólios bem construídos abrem portas que currículos tradicionais não conseguem abrir, especialmente para desenvolvedores sem experiência formal.', en: 'The portfolio concept comes from visual arts and architecture, where professionals present previous work to demonstrate capability. In software development, the principle is identical: showing what you have built as evidence of what you can build. The difference is that code without context communicates almost nothing. A repository with loose files, no README, no documentation, and no explanation of the problem it solves is invisible to recruiters and technical managers.\n\nThe portfolio solves a central problem: information asymmetry between candidate and employer. The employer does not know if you are competent; the portfolio reduces this uncertainty by providing concrete evidence. That is why presentation quality matters as much as code quality. A mediocre project well documented communicates more than an excellent project without context. The practical impact is direct: well-built portfolios open doors that traditional resumes cannot, especially for developers without formal experience.' } },
      { title: { pt: 'Funcionamento técnico: O que compõe um portfólio eficaz', en: 'Technical breakdown: What makes an effective portfolio' }, content: { pt: 'Um portfólio eficaz tem três componentes: seleção estratégica de projetos, documentação contextualizada e apresentação visual profissional. A seleção estratégica significa escolher 3 a 5 projetos que demonstrem habilidades diferentes e relevantes para o tipo de vaga que você busca. Para vagas de frontend, projetos com interfaces responsivas, acessibilidade e gerenciamento de estado. Para backend, APIs REST com autenticação, validação e tratamento de erros. A diversidade calculada demonstra amplitude; a profundidade em cada projeto demonstra competência.\n\nA documentação contextualizada vai além do README técnico. Cada projeto deve explicar: qual problema resolve, quais decisões técnicas foram tomadas e por quê, quais desafios foram encontrados e como foram superados, e qual foi o resultado final. Essa narrativa transforma código em história profissional. A apresentação visual pode ser um site pessoal simples mas bem construído, ou os próprios repositórios GitHub com READMEs ricos que incluem screenshots, diagramas de arquitetura e links para deploy. O formato importa menos que a clareza e profissionalismo da apresentação.', en: 'An effective portfolio has three components: strategic project selection, contextualized documentation, and professional visual presentation. Strategic selection means choosing 3 to 5 projects that demonstrate different and relevant skills for the type of position you seek. For frontend roles, projects with responsive interfaces, accessibility, and state management. For backend, REST APIs with authentication, validation, and error handling. Calculated diversity demonstrates breadth; depth in each project demonstrates competence.\n\nContextualized documentation goes beyond the technical README. Each project should explain: what problem it solves, what technical decisions were made and why, what challenges were encountered and how they were overcome, and what the final result was. This narrative transforms code into professional story. Visual presentation can be a simple but well-built personal site, or the GitHub repositories themselves with rich READMEs that include screenshots, architecture diagrams, and deploy links. Format matters less than clarity and professionalism of presentation.' } },
      { title: { pt: 'Erros comuns e interpretações equivocadas', en: 'Common mistakes and misconceptions' }, content: { pt: 'O erro mais frequente é quantidade sem qualidade: 20 repositórios com to-do lists, calculadoras e clones de tutorial. Isso não demonstra competência — demonstra que você seguiu instruções. Outro erro é não filtrar repositórios públicos: projetos abandonados, código desorganizado e exercícios incompletos poluem o perfil e passam uma impressão de descuido.\n\nTambém é equivocado acreditar que o portfólio precisa ter projetos comerciais ou profissionais. Projetos pessoais bem executados são perfeitamente válidos — o que importa é a demonstração de processo profissional, não a origem do projeto. Outro erro comum é copiar projetos populares sem adicionar valor próprio. Um clone do Twitter sem nenhuma diferenciação não demonstra criatividade nem capacidade de resolução de problemas originais.', en: 'The most frequent error is quantity without quality: 20 repositories with to-do lists, calculators, and tutorial clones. This does not demonstrate competence — it demonstrates you followed instructions. Another mistake is not filtering public repositories: abandoned projects, disorganized code, and incomplete exercises pollute the profile and give an impression of carelessness.\n\nIt is also wrong to believe the portfolio needs commercial or professional projects. Well-executed personal projects are perfectly valid — what matters is demonstrating professional process, not the project origin. Another common error is copying popular projects without adding your own value. A Twitter clone without any differentiation does not demonstrate creativity or original problem-solving ability.' } },
      { title: { pt: 'Aplicação prática no mundo real', en: 'Real-world practical application' }, content: { pt: 'Na prática, o portfólio é avaliado em diferentes momentos: na triagem inicial de currículo, onde recrutadores gastam segundos decidindo se você avança; na avaliação técnica, onde desenvolvedores seniores analisam qualidade de código; e na entrevista, onde você pode ser questionado sobre decisões técnicas dos seus projetos.\n\nPara cada momento, o portfólio precisa comunicar algo diferente. Para a triagem, o visual e a organização importam. Para a avaliação técnica, a qualidade do código, testes e arquitetura importam. Para a entrevista, a capacidade de explicar decisões e trade-offs importa. Um portfólio estratégico atende aos três momentos simultaneamente. Profissionais que entendem isso conseguem posições mesmo competindo com candidatos com mais experiência formal.', en: 'In practice, the portfolio is evaluated at different moments: in the initial resume screening, where recruiters spend seconds deciding if you advance; in the technical evaluation, where senior developers analyze code quality; and in the interview, where you may be questioned about technical decisions in your projects.\n\nFor each moment, the portfolio needs to communicate something different. For screening, visual presentation and organization matter. For technical evaluation, code quality, tests, and architecture matter. For the interview, the ability to explain decisions and trade-offs matters. A strategic portfolio addresses all three moments simultaneously. Professionals who understand this get positions even competing with candidates with more formal experience.' } },
      { title: { pt: 'O que isso significa para sua carreira', en: 'What this means for your career' }, content: { pt: 'Para o iniciante, o portfólio é frequentemente o único diferencial possível. Sem experiência profissional, certificações relevantes ou rede de contatos, os projetos pessoais são a evidência mais tangível de competência. O júnior que investe em um portfólio estratégico se posiciona acima de 90% dos candidatos do mesmo nível, simplesmente porque a maioria não faz esse investimento.\n\nPara o pleno, o portfólio evolui para demonstrar profundidade e especialização. Projetos mais complexos, contribuições open source, artigos técnicos e palestras complementam o código. Em entrevistas, a capacidade de explicar trade-offs e decisões arquiteturais dos projetos do portfólio demonstra maturidade que vai além do técnico. Empresas avaliam não apenas o que foi feito, mas como o candidato pensa sobre o que fez.', en: 'For the beginner, the portfolio is often the only possible differentiator. Without professional experience, relevant certifications, or professional network, personal projects are the most tangible evidence of competence. The junior who invests in a strategic portfolio positions themselves above 90% of candidates at the same level, simply because most do not make this investment.\n\nFor the mid-level, the portfolio evolves to demonstrate depth and specialization. More complex projects, open source contributions, technical articles, and talks complement the code. In interviews, the ability to explain trade-offs and architectural decisions of portfolio projects demonstrates maturity beyond the technical. Companies evaluate not only what was done, but how the candidate thinks about what they did.' } },
      { title: { pt: 'Conexão com a trilha', en: 'Connection with the trail' }, content: { pt: 'Este artigo inicia o Bloco 5, focado em presença profissional. Os blocos anteriores construíram os fundamentos que agora precisam ser demonstrados. Os próximos artigos abordam projetos estratégicos para iniciantes, o que não colocar no GitHub, como escrever READMEs profissionais, preparação para entrevistas e o que empresas realmente avaliam. Juntos, formam um guia completo para transformar conhecimento em oportunidade.', en: 'This article starts Block 5, focused on professional presence. The previous blocks built the fundamentals that now need to be demonstrated. The next articles cover strategic projects for beginners, what not to put on GitHub, how to write professional READMEs, interview preparation, and what companies really evaluate. Together, they form a complete guide for transforming knowledge into opportunity.' } },
      { title: { pt: 'Como aprofundar ainda mais este assunto', en: 'How to go deeper on this subject' }, content: { pt: 'Analise portfólios de desenvolvedores que foram contratados por empresas que você admira. Note não o que construíram, mas como apresentaram. Estude portfólios que foram compartilhados em processos seletivos abertos e observe os padrões que se repetem nos que foram aprovados. Peça feedback sobre seu portfólio a desenvolvedores seniores — eles podem identificar lacunas que você não percebe. Trate seu portfólio como um produto vivo que evolui junto com suas competências.', en: 'Analyze portfolios of developers who were hired by companies you admire. Note not what they built, but how they presented it. Study portfolios shared in open selection processes and observe patterns that repeat in those that were approved. Ask for portfolio feedback from senior developers — they can identify gaps you do not notice. Treat your portfolio as a living product that evolves alongside your competencies.' } },
      { title: { pt: 'Conclusão estratégica', en: 'Strategic conclusion' }, content: { pt: 'O portfólio não é um requisito burocrático — é a ferramenta mais poderosa que um desenvolvedor iniciante tem para demonstrar competência sem depender de experiência formal. Investir tempo na construção de um portfólio estratégico, bem documentado e com projetos que demonstrem raciocínio profissional é investir diretamente na velocidade da sua inserção no mercado. Poucos projetos bem apresentados valem mais que dezenas de repositórios sem contexto.', en: 'The portfolio is not a bureaucratic requirement — it is the most powerful tool a beginner developer has to demonstrate competence without relying on formal experience. Investing time in building a strategic, well-documented portfolio with projects that demonstrate professional reasoning is investing directly in the speed of your market insertion. A few well-presented projects are worth more than dozens of repositories without context.' } },
    ],
  },
  {
    id: 'mt-beginner-projects',
    slugPt: 'projetos-para-iniciantes',
    slugEn: 'projects-that-make-sense-for-beginners',
    title: { pt: 'Projetos Que Fazem Sentido Para Iniciantes', en: 'Projects That Make Sense for Beginners' },
    excerpt: { pt: 'Como escolher projetos de desenvolvimento que acelerem o aprendizado e demonstrem competência real.', en: 'How to choose development projects that accelerate learning and demonstrate real competence.' },
    date: { pt: '19 de Fevereiro, 2026', en: 'February 19, 2026' }, publishedDate: '2026-02-19', readTime: '22 min',
    tags: { pt: ['Projetos', 'Iniciantes', 'Prática'], en: ['Projects', 'Beginners', 'Practice'] },
    keywords: { pt: ['projetos para iniciantes', 'projetos programação', 'primeiro projeto', 'prática desenvolvimento'], en: ['beginner projects', 'programming projects', 'first project', 'development practice'] },
    sections: [
      { title: { pt: 'Introdução: O projeto como laboratório de aprendizado', en: 'Introduction: The project as a learning laboratory' }, content: { pt: 'O projeto pessoal é o laboratório onde teoria vira prática. Mas a maioria dos iniciantes escolhe projetos que não agregam valor ao aprendizado nem ao portfólio: to-do lists genéricas, calculadoras básicas, clones superficiais de redes sociais. O problema não é a simplicidade — é a falta de intencionalidade. Um projeto simples que resolve um problema real e é executado com práticas profissionais vale infinitamente mais do que um projeto complexo que é apenas um exercício acadêmico.\n\nEste artigo conecta diretamente com o anterior sobre portfólio. Se o portfólio é a vitrine, os projetos são os produtos expostos. A qualidade e relevância dos projetos determinam a eficácia do portfólio como ferramenta de posicionamento profissional.', en: 'The personal project is the laboratory where theory becomes practice. But most beginners choose projects that add no value to learning or portfolio: generic to-do lists, basic calculators, superficial social network clones. The problem is not simplicity — it is the lack of intentionality. A simple project that solves a real problem and is executed with professional practices is worth infinitely more than a complex project that is just an academic exercise.\n\nThis article connects directly with the previous one about portfolios. If the portfolio is the showcase, the projects are the displayed products. The quality and relevance of projects determine the portfolio\'s effectiveness as a professional positioning tool.' } },
      { title: { pt: 'Base conceitual: Projetos com propósito vs exercícios', en: 'Conceptual foundation: Projects with purpose vs exercises' }, content: { pt: 'A distinção fundamental é entre projetos com propósito e exercícios de aprendizado. Exercícios existem para praticar conceitos isolados e não precisam ir para o portfólio. Projetos com propósito resolvem problemas identificáveis e demonstram a capacidade de pensar em soluções completas. Isso não exige complexidade — exige contexto e intenção.\n\nUm sistema de gerenciamento de tarefas pessoal que inclui autenticação, CRUD completo, filtros e responsividade é um projeto com propósito. Ele demonstra domínio de múltiplas competências integradas. Uma calculadora que soma números é um exercício. Ambos têm valor para o aprendizado, mas apenas o primeiro tem valor para o portfólio. O impacto prático dessa distinção é que iniciantes que escolhem projetos com propósito aprendem mais rápido porque lidam com a complexidade real do desenvolvimento de software, não com versões simplificadas artificialmente.', en: 'The fundamental distinction is between projects with purpose and learning exercises. Exercises exist to practice isolated concepts and do not need to go in the portfolio. Projects with purpose solve identifiable problems and demonstrate the ability to think in complete solutions. This does not require complexity — it requires context and intention.\n\nA personal task management system that includes authentication, complete CRUD, filters, and responsiveness is a project with purpose. It demonstrates mastery of multiple integrated competencies. A calculator that adds numbers is an exercise. Both have value for learning, but only the first has value for the portfolio. The practical impact of this distinction is that beginners who choose purposeful projects learn faster because they deal with the real complexity of software development, not artificially simplified versions.' } },
      { title: { pt: 'Funcionamento técnico: Critérios para escolher projetos', en: 'Technical breakdown: Criteria for choosing projects' }, content: { pt: 'Projetos estratégicos para iniciantes seguem critérios específicos. Primeiro, devem envolver pelo menos três tecnologias integradas (por exemplo: React + API REST + banco de dados). Segundo, devem resolver um problema que você pode explicar em uma frase. Terceiro, devem ter escopo definido — algo que pode ser concluído em 2 a 4 semanas de trabalho dedicado. Quarto, devem envolver pelo menos um desafio que você não sabe resolver no início.\n\nExemplos concretos: um dashboard de finanças pessoais que consome dados de uma API e exibe gráficos; uma plataforma de links (tipo Linktree) com painel de administração; um sistema de agendamentos com notificações por email; um blog com sistema de comentários e painel de publicação. Cada um desses projetos exercita front-end, back-end, banco de dados, autenticação e deploy — competências que o mercado exige e que demonstram capacidade profissional.', en: 'Strategic projects for beginners follow specific criteria. First, they should involve at least three integrated technologies (for example: React + REST API + database). Second, they should solve a problem you can explain in one sentence. Third, they should have defined scope — something that can be completed in 2 to 4 weeks of dedicated work. Fourth, they should involve at least one challenge you do not know how to solve at the start.\n\nConcrete examples: a personal finance dashboard that consumes API data and displays charts; a link platform (Linktree-type) with admin panel; a scheduling system with email notifications; a blog with comment system and publishing panel. Each of these projects exercises front-end, back-end, database, authentication, and deploy — competencies the market demands and that demonstrate professional capability.' } },
      { title: { pt: 'Erros comuns e interpretações equivocadas', en: 'Common mistakes and misconceptions' }, content: { pt: 'O erro mais comum é começar projetos grandes demais e nunca terminar. Um projeto incompleto no portfólio é pior do que nenhum projeto — comunica que você não consegue entregar. Outro erro é escolher projetos baseados no que é popular em vez do que é estratégico para sua carreira. Fazer um clone do Netflix porque viu no YouTube é seguir tendência, não demonstrar competência.\n\nTambém é equivocado pensar que o projeto precisa ser original. Resolver um problema comum de forma bem executada é perfeitamente válido. O que importa não é a originalidade da ideia, mas a qualidade da execução e a capacidade de explicar as decisões tomadas. Outro erro é trabalhar sempre sozinho — contribuir em projetos de outros, mesmo que pequenos, demonstra capacidade de colaboração que projetos solo não demonstram.', en: 'The most common error is starting projects too large and never finishing. An incomplete project in the portfolio is worse than no project — it communicates you cannot deliver. Another mistake is choosing projects based on what is popular instead of what is strategic for your career. Making a Netflix clone because you saw it on YouTube is following trends, not demonstrating competence.\n\nIt is also wrong to think the project needs to be original. Solving a common problem with good execution is perfectly valid. What matters is not the originality of the idea, but the quality of execution and the ability to explain decisions made. Another error is always working alone — contributing to others\' projects, even small ones, demonstrates collaboration ability that solo projects do not.' } },
      { title: { pt: 'Aplicação prática no mundo real', en: 'Real-world practical application' }, content: { pt: 'No mercado real, os projetos que mais impressionam recrutadores não são os mais complexos — são os mais bem apresentados e que demonstram processo profissional. Um projeto com commits organizados, branches para features, README detalhado, testes básicos e deploy funcional demonstra maturidade que a maioria dos candidatos iniciantes não tem.\n\nEmpresas avaliam projetos de portfólio buscando sinais de como o candidato trabalha, não apenas o que sabe fazer. Um histórico de commits que mostra evolução incremental, mensagens descritivas e resolução de problemas é mais valioso do que um repositório perfeito com um único commit. O processo é tão importante quanto o resultado.', en: 'In the real market, projects that most impress recruiters are not the most complex — they are the best presented and demonstrate professional process. A project with organized commits, feature branches, detailed README, basic tests, and functional deploy demonstrates maturity most beginner candidates lack.\n\nCompanies evaluate portfolio projects looking for signals of how the candidate works, not just what they know. A commit history showing incremental evolution, descriptive messages, and problem-solving is more valuable than a perfect repository with a single commit. The process is as important as the result.' } },
      { title: { pt: 'O que isso significa para sua carreira', en: 'What this means for your career' }, content: { pt: 'O tipo de projeto que você escolhe construir comunica suas prioridades e seu nível de maturidade. Iniciantes que constroem projetos utilitários demonstram pragmatismo. Aqueles que constroem projetos que resolvem problemas reais demonstram visão de produto. Aqueles que documentam cada decisão demonstram comunicação profissional. Essas qualidades são avaliadas em entrevistas e definem a velocidade da progressão na carreira.\n\nEm entrevistas técnicas, ser capaz de explicar por que escolheu determinada tecnologia, como lidou com um problema específico e o que faria diferente demonstra profundidade que o código sozinho não transmite. Projetos estratégicos criam oportunidades para essas conversas; exercícios genéricos não criam.', en: 'The type of project you choose to build communicates your priorities and maturity level. Beginners who build utility projects demonstrate pragmatism. Those who build projects solving real problems demonstrate product vision. Those who document every decision demonstrate professional communication. These qualities are evaluated in interviews and define career progression speed.\n\nIn technical interviews, being able to explain why you chose a certain technology, how you handled a specific problem, and what you would do differently demonstrates depth that code alone does not convey. Strategic projects create opportunities for these conversations; generic exercises do not.' } },
      { title: { pt: 'Conexão com a trilha', en: 'Connection with the trail' }, content: { pt: 'Este artigo complementa o anterior sobre portfólio, fornecendo critérios concretos para escolher o que construir. Os próximos artigos abordam o que não colocar no GitHub e como estruturar READMEs profissionais, completando o ciclo de construção de presença técnica visível.', en: 'This article complements the previous one about portfolios, providing concrete criteria for choosing what to build. The next articles cover what not to put on GitHub and how to structure professional READMEs, completing the cycle of building visible technical presence.' } },
      { title: { pt: 'Como aprofundar ainda mais este assunto', en: 'How to go deeper on this subject' }, content: { pt: 'Identifique problemas no seu dia a dia que poderiam ser resolvidos com software. Cada irritação, processo manual ou ineficiência é uma oportunidade de projeto. Converse com pessoas de outras áreas sobre seus problemas operacionais — essas conversas geram ideias de projetos que demonstram capacidade de resolver problemas reais, não apenas exercícios acadêmicos. Participe de hackathons e desafios de programação para expandir sua exposição a problemas variados.', en: 'Identify problems in your daily life that could be solved with software. Every annoyance, manual process, or inefficiency is a project opportunity. Talk to people from other fields about their operational problems — these conversations generate project ideas that demonstrate ability to solve real problems, not just academic exercises. Participate in hackathons and programming challenges to expand your exposure to varied problems.' } },
      { title: { pt: 'Conclusão estratégica', en: 'Strategic conclusion' }, content: { pt: 'Projetos não são apenas veículos de aprendizado — são declarações de competência. Cada projeto que você escolhe construir, documenta e publica é uma afirmação profissional. Escolher projetos com propósito, executá-los com processo profissional e apresentá-los com contexto é a forma mais eficiente de transformar conhecimento teórico em evidência verificável de capacidade. Poucos projetos estratégicos superam dezenas de exercícios genéricos.', en: 'Projects are not just learning vehicles — they are competence statements. Each project you choose to build, document, and publish is a professional assertion. Choosing projects with purpose, executing them with professional process, and presenting them with context is the most efficient way to transform theoretical knowledge into verifiable evidence of capability. A few strategic projects surpass dozens of generic exercises.' } },
    ],
  },
  {
    id: 'mt-what-not-github',
    slugPt: 'o-que-nao-colocar-no-github',
    slugEn: 'what-not-to-put-on-github',
    title: { pt: 'O Que Não Colocar no Seu GitHub', en: 'What Not to Put on Your GitHub' },
    excerpt: { pt: 'Erros comuns que enfraquecem o perfil GitHub de um desenvolvedor e como manter um repositório profissional.', en: 'Common mistakes that weaken a developer\'s GitHub profile and how to maintain a professional repository.' },
    date: { pt: '19 de Fevereiro, 2026', en: 'February 19, 2026' }, publishedDate: '2026-02-19', readTime: '20 min',
    tags: { pt: ['GitHub', 'Portfólio', 'Profissionalismo'], en: ['GitHub', 'Portfolio', 'Professionalism'] },
    keywords: { pt: ['github profissional', 'erros github', 'perfil github', 'repositórios profissionais'], en: ['professional github', 'github mistakes', 'github profile', 'professional repositories'] },
    sections: [
      { title: { pt: 'Introdução: Seu GitHub é sua vitrine técnica', en: 'Introduction: Your GitHub is your technical showcase' }, content: { pt: 'O GitHub é frequentemente o primeiro contato que um recrutador ou líder técnico tem com o seu trabalho. Antes de ler seu currículo ou agendar uma entrevista, muitos profissionais de contratação visitam seu perfil para avaliar a qualidade do que você produz. Se o que encontram é uma coleção desorganizada de exercícios incompletos, código sem documentação e repositórios abandonados, a impressão é negativa antes mesmo do primeiro contato.\n\nEste artigo complementa diretamente os anteriores sobre portfólio e projetos estratégicos. Enquanto aqueles focaram no que construir e como apresentar, este foca no que evitar. Saber o que não publicar é tão importante quanto saber o que publicar — e frequentemente mais negligenciado.', en: 'GitHub is often the first contact a recruiter or technical lead has with your work. Before reading your resume or scheduling an interview, many hiring professionals visit your profile to evaluate the quality of what you produce. If what they find is a disorganized collection of incomplete exercises, undocumented code, and abandoned repositories, the impression is negative before the first contact.\n\nThis article directly complements the previous ones about portfolio and strategic projects. While those focused on what to build and how to present, this focuses on what to avoid. Knowing what not to publish is as important as knowing what to publish — and frequently more neglected.' } },
      { title: { pt: 'Base conceitual: Curadoria como competência profissional', en: 'Conceptual foundation: Curation as professional competence' }, content: { pt: 'Curadoria é a competência de selecionar, organizar e apresentar informação de forma que maximize valor e minimize ruído. No contexto do GitHub, curadoria significa manter visíveis apenas os repositórios que representam seu melhor trabalho e arquivar ou tornar privados aqueles que não agregam valor. Isso não é desonestidade — é comunicação profissional.\n\nO problema que a curadoria resolve é o excesso de informação. Quando tudo está visível, nada se destaca. O recrutador que encontra 50 repositórios públicos não vai avaliar todos — vai olhar os 3 primeiros e tirar conclusões. Se esses 3 são exercícios básicos de tutorial, a conclusão será que esse é seu nível de competência, mesmo que entre os outros 47 existam projetos excelentes. Curadoria garante que os melhores trabalhos estejam sempre em evidência.', en: 'Curation is the competence of selecting, organizing, and presenting information in a way that maximizes value and minimizes noise. In the GitHub context, curation means keeping visible only repositories that represent your best work and archiving or making private those that add no value. This is not dishonesty — it is professional communication.\n\nThe problem curation solves is information overload. When everything is visible, nothing stands out. The recruiter who finds 50 public repositories will not evaluate all — they will look at the first 3 and draw conclusions. If those 3 are basic tutorial exercises, the conclusion will be that this is your competence level, even if among the other 47 there are excellent projects. Curation ensures the best work is always prominent.' } },
      { title: { pt: 'Funcionamento técnico: O que remover ou arquivar', en: 'Technical breakdown: What to remove or archive' }, content: { pt: 'Categorias específicas que devem ser removidas ou tornadas privadas: forks que você nunca modificou, exercícios de cursos sem valor adicional, projetos abandonados sem README, repositórios de teste com nomes genéricos, código com credenciais expostas (mesmo revogadas), projetos com código copiado sem atribuição. Cada um desses itens enfraquece seu perfil de formas diferentes.\n\nForks não modificados inflam o número de repositórios sem adicionar valor. Exercícios de curso demonstram que você seguiu instruções, não que sabe resolver problemas. Projetos abandonados sugerem falta de consistência. Repositórios de teste com nomes como "test", "temp" ou "asdf" demonstram descuido. Credenciais expostas, mesmo em repositórios antigos, demonstram falta de consciência de segurança. Código copiado sem atribuição demonstra falta de ética profissional.', en: 'Specific categories that should be removed or made private: forks you never modified, course exercises without additional value, abandoned projects without README, test repositories with generic names, code with exposed credentials (even revoked), projects with copied code without attribution. Each of these items weakens your profile in different ways.\n\nUnmodified forks inflate repository count without adding value. Course exercises demonstrate you followed instructions, not that you can solve problems. Abandoned projects suggest lack of consistency. Test repositories with names like "test", "temp" or "asdf" demonstrate carelessness. Exposed credentials, even in old repositories, demonstrate lack of security awareness. Copied code without attribution demonstrates lack of professional ethics.' } },
      { title: { pt: 'Erros comuns e interpretações equivocadas', en: 'Common mistakes and misconceptions' }, content: { pt: 'O erro mais comum é pensar que mais repositórios significa mais competência. Significa mais ruído. Outro erro é não configurar o perfil GitHub adequadamente: sem bio, sem foto profissional, sem link para portfólio ou LinkedIn. Essas informações básicas fazem diferença na primeira impressão.\n\nTambém é equivocado pensar que ninguém olha o histórico de commits. Recrutadores técnicos frequentemente analisam padrões de commits: frequência, qualidade das mensagens, consistência. Mensagens como "fix", "update" ou "aaa" em todos os commits demonstram falta de disciplina profissional. Commits atômicos com mensagens descritivas demonstram processo organizado.', en: 'The most common error is thinking more repositories means more competence. It means more noise. Another mistake is not properly configuring the GitHub profile: no bio, no professional photo, no link to portfolio or LinkedIn. This basic information makes a difference in first impression.\n\nIt is also wrong to think nobody looks at commit history. Technical recruiters frequently analyze commit patterns: frequency, message quality, consistency. Messages like "fix", "update" or "aaa" in all commits demonstrate lack of professional discipline. Atomic commits with descriptive messages demonstrate organized process.' } },
      { title: { pt: 'Aplicação prática no mundo real', en: 'Real-world practical application' }, content: { pt: 'No processo seletivo real, o GitHub funciona como filtro silencioso. Empresas de tecnologia frequentemente incluem análise de perfil GitHub como etapa do processo. Algumas utilizam ferramentas automatizadas que analisam frequência de contribuição, linguagens usadas e qualidade de documentação. Outras pedem que candidatos indiquem seus melhores repositórios para avaliação detalhada.\n\nProfissionais que mantêm perfis curados e organizados se beneficiam dessas análises. Aqueles com perfis poluídos são prejudicados antes mesmo de ter chance de explicar. A regra prática é: se você não teria orgulho de mostrar um repositório em uma entrevista, ele não deveria estar público.', en: 'In real selection processes, GitHub functions as a silent filter. Technology companies frequently include GitHub profile analysis as a process step. Some use automated tools that analyze contribution frequency, languages used, and documentation quality. Others ask candidates to indicate their best repositories for detailed evaluation.\n\nProfessionals who maintain curated and organized profiles benefit from these analyses. Those with polluted profiles are harmed before even having a chance to explain. The practical rule is: if you would not be proud to show a repository in an interview, it should not be public.' } },
      { title: { pt: 'O que isso significa para sua carreira', en: 'What this means for your career' }, content: { pt: 'O GitHub é uma extensão do seu currículo — e como qualquer documento profissional, deve ser mantido com cuidado. A diferença entre um perfil curado e um abandonado pode significar a diferença entre receber uma chamada para entrevista e ser ignorado. Desenvolvedores que entendem o GitHub como ferramenta de posicionamento profissional, não apenas como backup de código, avançam mais rapidamente na carreira.\n\nEm níveis mais avançados, o GitHub também serve como plataforma de construção de reputação: contribuições para projetos open source, publicação de bibliotecas e ferramentas, e participação em discussões técnicas constroem autoridade que vai além do portfólio pessoal.', en: 'GitHub is an extension of your resume — and like any professional document, it should be maintained with care. The difference between a curated and an abandoned profile can mean the difference between receiving an interview call and being ignored. Developers who understand GitHub as a professional positioning tool, not just a code backup, advance more quickly in their career.\n\nAt more advanced levels, GitHub also serves as a reputation-building platform: contributions to open source projects, publishing libraries and tools, and participating in technical discussions build authority that goes beyond personal portfolio.' } },
      { title: { pt: 'Conexão com a trilha', en: 'Connection with the trail' }, content: { pt: 'Este artigo complementa diretamente os anteriores sobre portfólio e projetos. O próximo artigo aborda como estruturar READMEs profissionais, que é a ponte entre o código e a comunicação do valor que ele representa. Juntos, os três artigos formam um sistema completo de presença técnica profissional.', en: 'This article directly complements the previous ones about portfolio and projects. The next article covers how to structure professional READMEs, which is the bridge between code and communication of the value it represents. Together, the three articles form a complete system of professional technical presence.' } },
      { title: { pt: 'Como aprofundar ainda mais este assunto', en: 'How to go deeper on this subject' }, content: { pt: 'Faça uma auditoria completa do seu perfil GitHub agora. Liste todos os repositórios públicos e classifique cada um em três categorias: destaque (mantém público e melhora), neutro (pode ficar mas não agrega) e ruído (deve ser arquivado ou tornado privado). Implemente a curadoria imediatamente. Revise seu perfil mensalmente para manter a qualidade consistente. Peça a alguém de confiança que avalie seu perfil como se fosse um recrutador e use o feedback para ajustar.', en: 'Do a complete audit of your GitHub profile now. List all public repositories and classify each into three categories: highlight (keep public and improve), neutral (can stay but adds nothing), and noise (should be archived or made private). Implement curation immediately. Review your profile monthly to maintain consistent quality. Ask someone you trust to evaluate your profile as if they were a recruiter and use the feedback to adjust.' } },
      { title: { pt: 'Conclusão estratégica', en: 'Strategic conclusion' }, content: { pt: 'O GitHub profissional não é o mais populado — é o mais curado. Qualidade absoluta em poucos repositórios supera quantidade em dezenas. Tratar seu GitHub como uma vitrine profissional, não como uma gaveta de rascunhos, é uma decisão simples que gera impacto desproporcional na velocidade de inserção no mercado. A curadoria é uma competência profissional que se reflete em todas as áreas do trabalho.', en: 'The professional GitHub is not the most populated — it is the most curated. Absolute quality in few repositories surpasses quantity in dozens. Treating your GitHub as a professional showcase, not a drawer of drafts, is a simple decision that generates disproportionate impact on market insertion speed. Curation is a professional competence reflected in all areas of work.' } },
    ],
  },
  {
    id: 'mt-professional-readme',
    slugPt: 'readme-profissional',
    slugEn: 'professional-readme',
    title: { pt: 'Como Estruturar um README Profissional', en: 'How to Structure a Professional README' },
    excerpt: { pt: 'Guia prático para criar READMEs que comunicam valor, facilitam avaliação e demonstram maturidade profissional.', en: 'Practical guide to creating READMEs that communicate value, facilitate evaluation, and demonstrate professional maturity.' },
    date: { pt: '19 de Fevereiro, 2026', en: 'February 19, 2026' }, publishedDate: '2026-02-19', readTime: '20 min',
    tags: { pt: ['Documentação', 'GitHub', 'Comunicação'], en: ['Documentation', 'GitHub', 'Communication'] },
    keywords: { pt: ['readme profissional', 'documentação projeto', 'github readme', 'comunicação técnica'], en: ['professional readme', 'project documentation', 'github readme', 'technical communication'] },
    sections: [
      { title: { pt: 'Introdução: O README como primeira impressão do seu código', en: 'Introduction: The README as first impression of your code' }, content: { pt: 'O README é o documento mais importante de qualquer repositório. É a primeira coisa que qualquer visitante lê — antes de explorar o código, antes de testar a aplicação, antes de considerar contribuir. Um README ausente ou genérico comunica descuido; um README bem estruturado comunica profissionalismo e respeito pelo tempo de quem lê.\n\nPara desenvolvedores em processo de construção de portfólio, o README é frequentemente a diferença entre um recrutador entender o valor de um projeto ou ignorá-lo. Este artigo é o terceiro do Bloco 5 sobre presença profissional e fecha o ciclo de construção de repositórios que comunicam competência.', en: 'The README is the most important document of any repository. It is the first thing any visitor reads — before exploring the code, before testing the application, before considering contributing. An absent or generic README communicates carelessness; a well-structured README communicates professionalism and respect for the reader\'s time.\n\nFor developers building their portfolio, the README is often the difference between a recruiter understanding a project\'s value or ignoring it. This article is the third in Block 5 on professional presence and closes the cycle of building repositories that communicate competence.' } },
      { title: { pt: 'Base conceitual: Documentação como comunicação', en: 'Conceptual foundation: Documentation as communication' }, content: { pt: 'Documentação não é uma tarefa administrativa — é comunicação profissional. O README responde às perguntas que qualquer pessoa terá ao encontrar seu projeto: O que é isso? Que problema resolve? Como funciono? Como instalo? Como contribuo? Cada resposta ausente é uma barreira que afasta potenciais interessados.\n\nO conceito subjacente é empatia técnica: a capacidade de se colocar no lugar de quem encontra seu código pela primeira vez. Essa pessoa não tem o contexto que você tem. Ela não sabe por que certas decisões foram tomadas, quais são os requisitos, ou como configurar o ambiente. O README é a ponte entre o seu conhecimento interno e o entendimento externo. Profissionais que dominam essa ponte são mais valorizados porque facilitam o trabalho de todos ao seu redor.', en: 'Documentation is not an administrative task — it is professional communication. The README answers the questions anyone will have when finding your project: What is this? What problem does it solve? How does it work? How do I install it? How do I contribute? Each unanswered question is a barrier that drives away potential interested parties.\n\nThe underlying concept is technical empathy: the ability to put yourself in the place of someone encountering your code for the first time. That person does not have the context you have. They do not know why certain decisions were made, what the requirements are, or how to configure the environment. The README is the bridge between your internal knowledge and external understanding. Professionals who master this bridge are more valued because they facilitate everyone\'s work around them.' } },
      { title: { pt: 'Funcionamento técnico: Estrutura de um README eficaz', en: 'Technical breakdown: Structure of an effective README' }, content: { pt: 'Um README profissional segue uma estrutura previsível: título claro, descrição breve do projeto (1-2 parágrafos), screenshots ou GIFs da interface, tecnologias utilizadas, instruções de instalação e execução, estrutura de pastas, funcionalidades principais, decisões técnicas relevantes, status do projeto e informações de contato ou contribuição.\n\nCada seção tem uma função comunicacional específica. O título e a descrição vendem o projeto. As screenshots demonstram o resultado. As tecnologias informam o contexto técnico. As instruções de instalação demonstram que o projeto funciona e pode ser reproduzido. As decisões técnicas demonstram maturidade. O status informa se o projeto está ativo, em manutenção ou finalizado. Essa estrutura é universalmente reconhecida e facilita a avaliação por qualquer profissional técnico.', en: 'A professional README follows a predictable structure: clear title, brief project description (1-2 paragraphs), screenshots or GIFs of the interface, technologies used, installation and execution instructions, folder structure, main features, relevant technical decisions, project status, and contact or contribution information.\n\nEach section has a specific communicational function. The title and description sell the project. Screenshots demonstrate the result. Technologies inform the technical context. Installation instructions demonstrate the project works and can be reproduced. Technical decisions demonstrate maturity. Status informs whether the project is active, in maintenance, or completed. This structure is universally recognized and facilitates evaluation by any technical professional.' } },
      { title: { pt: 'Erros comuns e interpretações equivocadas', en: 'Common mistakes and misconceptions' }, content: { pt: 'O erro mais grave é não ter README algum. O segundo mais grave é ter um README gerado automaticamente e não editado, o que demonstra indiferença explícita. Outro erro frequente é escrever READMEs excessivamente longos e desorganizados — a comunicação eficaz é concisa e estruturada.\n\nTambém é equivocado tratar o README como estático. Ele deve evoluir com o projeto. Instruções desatualizadas são piores que instruções ausentes porque geram frustração ativa em quem tenta seguir. Outro erro comum é não incluir screenshots — em projetos visuais, uma imagem comunica mais em 2 segundos do que 10 parágrafos de texto.', en: 'The most serious error is having no README at all. The second most serious is having an auto-generated and unedited README, which demonstrates explicit indifference. Another frequent mistake is writing excessively long and disorganized READMEs — effective communication is concise and structured.\n\nIt is also wrong to treat the README as static. It should evolve with the project. Outdated instructions are worse than absent instructions because they generate active frustration in those trying to follow them. Another common error is not including screenshots — in visual projects, an image communicates more in 2 seconds than 10 paragraphs of text.' } },
      { title: { pt: 'Aplicação prática no mundo real', en: 'Real-world practical application' }, content: { pt: 'No ambiente profissional, a qualidade da documentação de um desenvolvedor é observada diariamente: em pull requests, wikis internas, mensagens de commit, comentários de código e documentação de APIs. O README é apenas a manifestação mais visível de uma competência que permeia todo o trabalho. Profissionais que documentam bem são consistentemente mais valorizados porque reduzem o custo de comunicação da equipe inteira.\n\nEm processos seletivos, alguns empregadores utilizam a qualidade do README como proxy para qualidade de comunicação. Se o candidato não consegue explicar seu próprio projeto de forma clara e estruturada, provavelmente terá dificuldade em comunicar decisões técnicas complexas em reuniões, code reviews e documentação interna.', en: 'In the professional environment, the quality of a developer\'s documentation is observed daily: in pull requests, internal wikis, commit messages, code comments, and API documentation. The README is just the most visible manifestation of a competence that permeates all work. Professionals who document well are consistently more valued because they reduce the communication cost of the entire team.\n\nIn selection processes, some employers use README quality as a proxy for communication quality. If the candidate cannot explain their own project clearly and structuredly, they will probably have difficulty communicating complex technical decisions in meetings, code reviews, and internal documentation.' } },
      { title: { pt: 'O que isso significa para sua carreira', en: 'What this means for your career' }, content: { pt: 'A capacidade de documentar com clareza é uma das competências que mais distingue desenvolvedores em progressão de carreira. Júniores que documentam bem são promovidos mais rapidamente porque demonstram maturidade comunicacional. Plenos que produzem documentação excelente são candidatos naturais a posições de liderança técnica porque facilitam o onboarding de novos membros e a transmissão de conhecimento.\n\nEm entrevistas, mencionar que você trata documentação como parte integral do desenvolvimento — não como uma tarefa secundária — demonstra maturidade profissional que a maioria dos candidatos do mesmo nível não possui. Essa distinção é notada e valorizada por líderes técnicos experientes.', en: 'The ability to document clearly is one of the competencies that most distinguishes developers in career progression. Juniors who document well are promoted faster because they demonstrate communicational maturity. Mid-levels who produce excellent documentation are natural candidates for technical leadership positions because they facilitate onboarding of new members and knowledge transfer.\n\nIn interviews, mentioning that you treat documentation as an integral part of development — not a secondary task — demonstrates professional maturity most candidates at the same level do not possess. This distinction is noticed and valued by experienced technical leaders.' } },
      { title: { pt: 'Conexão com a trilha', en: 'Connection with the trail' }, content: { pt: 'Este artigo fecha o ciclo de presença técnica iniciado com portfólio e projetos. Os próximos artigos do bloco abordam preparação para entrevistas e o que empresas realmente avaliam em iniciantes, conectando a construção de presença com a efetiva inserção no mercado.', en: 'This article closes the technical presence cycle started with portfolio and projects. The next articles in the block cover interview preparation and what companies really evaluate in beginners, connecting presence building with effective market insertion.' } },
      { title: { pt: 'Como aprofundar ainda mais este assunto', en: 'How to go deeper on this subject' }, content: { pt: 'Estude READMEs de projetos open source populares no GitHub. Note a estrutura, a clareza e os elementos visuais utilizados. Use ferramentas como shields.io para adicionar badges profissionais. Crie templates de README que você pode reutilizar em seus projetos, adaptando para cada contexto. Peça feedback sobre seus READMEs a desenvolvedores mais experientes e itere com base nas sugestões.', en: 'Study READMEs of popular open source projects on GitHub. Note the structure, clarity, and visual elements used. Use tools like shields.io to add professional badges. Create README templates you can reuse in your projects, adapting for each context. Ask more experienced developers for feedback on your READMEs and iterate based on suggestions.' } },
      { title: { pt: 'Conclusão estratégica', en: 'Strategic conclusion' }, content: { pt: 'O README é o cartão de visita do seu código. Investir tempo em READMEs bem estruturados não é perfeccionismo — é comunicação profissional estratégica. Um projeto com README excelente comunica mais valor do que um projeto tecnicamente superior sem documentação. Essa é uma das poucas áreas onde um investimento de 30 minutos pode mudar fundamentalmente como seu trabalho é percebido pelo mercado.', en: 'The README is your code\'s business card. Investing time in well-structured READMEs is not perfectionism — it is strategic professional communication. A project with an excellent README communicates more value than a technically superior project without documentation. This is one of the few areas where a 30-minute investment can fundamentally change how your work is perceived by the market.' } },
    ],
  },
  {
    id: 'mt-technical-interviews',
    slugPt: 'preparacao-entrevistas-tecnicas',
    slugEn: 'preparing-for-technical-interviews',
    title: { pt: 'Como Se Preparar Para Entrevistas Técnicas', en: 'How to Prepare for Technical Interviews' },
    excerpt: { pt: 'Estratégias práticas para enfrentar entrevistas técnicas com preparação sólida e postura profissional.', en: 'Practical strategies to face technical interviews with solid preparation and professional posture.' },
    date: { pt: '19 de Fevereiro, 2026', en: 'February 19, 2026' }, publishedDate: '2026-02-19', readTime: '24 min',
    tags: { pt: ['Entrevistas', 'Carreira', 'Preparação'], en: ['Interviews', 'Career', 'Preparation'] },
    keywords: { pt: ['entrevista técnica', 'preparação entrevista', 'processo seletivo dev', 'entrevista programação'], en: ['technical interview', 'interview preparation', 'dev selection process', 'programming interview'] },
    sections: [
      { title: { pt: 'Introdução: A entrevista como demonstração de processo mental', en: 'Introduction: The interview as mental process demonstration' }, content: { pt: 'A entrevista técnica não é um exame de conhecimento — é uma demonstração de como você pensa, comunica e resolve problemas sob pressão. Empresas não contratam quem sabe todas as respostas; contratam quem demonstra processo de raciocínio sólido, capacidade de aprender e postura profissional. Entender essa distinção muda fundamentalmente a forma como você se prepara.\n\nEste artigo faz parte do Bloco 5 sobre inserção no mercado. Os artigos anteriores construíram a presença técnica visível (portfólio, projetos, GitHub, README). Agora o foco é a preparação para o momento em que essa presença gera oportunidades concretas: a entrevista.', en: 'The technical interview is not a knowledge exam — it is a demonstration of how you think, communicate, and solve problems under pressure. Companies do not hire those who know all answers; they hire those who demonstrate solid reasoning process, learning ability, and professional posture. Understanding this distinction fundamentally changes how you prepare.\n\nThis article is part of Block 5 on market insertion. Previous articles built visible technical presence (portfolio, projects, GitHub, README). Now the focus is preparation for the moment when that presence generates concrete opportunities: the interview.' } },
      { title: { pt: 'Base conceitual: O que a entrevista realmente avalia', en: 'Conceptual foundation: What the interview really evaluates' }, content: { pt: 'Entrevistas técnicas avaliam três dimensões: competência técnica (você sabe fazer?), processo de raciocínio (como você pensa?) e adequação cultural (você se encaixa na equipe?). A maioria dos candidatos se prepara apenas para a primeira dimensão e é eliminada nas outras duas.\n\nA competência técnica é o requisito mínimo. O processo de raciocínio é o diferenciador. A adequação cultural é o desempate. Quando dois candidatos demonstram competência técnica equivalente, aquele que comunica melhor seu raciocínio e demonstra postura colaborativa é selecionado. Isso explica por que desenvolvedores tecnicamente competentes são rejeitados e por que candidatos com gaps técnicos são aprovados quando demonstram potencial de crescimento e boa comunicação.', en: 'Technical interviews evaluate three dimensions: technical competence (can you do it?), reasoning process (how do you think?), and cultural fit (do you fit the team?). Most candidates prepare only for the first dimension and are eliminated in the other two.\n\nTechnical competence is the minimum requirement. Reasoning process is the differentiator. Cultural fit is the tiebreaker. When two candidates demonstrate equivalent technical competence, the one who better communicates their reasoning and demonstrates collaborative posture is selected. This explains why technically competent developers are rejected and why candidates with technical gaps are approved when they demonstrate growth potential and good communication.' } },
      { title: { pt: 'Funcionamento técnico: Tipos de entrevista e como abordar cada uma', en: 'Technical breakdown: Types of interviews and how to approach each' }, content: { pt: 'Os principais formatos são: entrevista conversacional (discussão sobre experiência e projetos), live coding (resolver um problema em tempo real), take-home challenge (projeto para fazer em casa com prazo), e system design (projetar a arquitetura de um sistema). Cada formato exige preparação diferente.\n\nNa conversacional, pratique explicar seus projetos em termos de problemas resolvidos e decisões tomadas, não tecnologias usadas. No live coding, pratique resolver problemas verbalizando seu raciocínio — o entrevistador quer ouvir como você pensa, não apenas ver o resultado. No take-home, trate como um projeto profissional: commits organizados, testes, documentação e deploy. No system design, pratique decompor problemas grandes em componentes menores e discutir trade-offs de cada decisão. A verbalização do raciocínio é o fator mais importante em todos os formatos.', en: 'The main formats are: conversational interview (discussion about experience and projects), live coding (solving a problem in real time), take-home challenge (project to do at home with deadline), and system design (designing a system\'s architecture). Each format requires different preparation.\n\nIn conversational, practice explaining your projects in terms of problems solved and decisions made, not technologies used. In live coding, practice solving problems while verbalizing your reasoning — the interviewer wants to hear how you think, not just see the result. In take-home, treat it as a professional project: organized commits, tests, documentation, and deploy. In system design, practice decomposing large problems into smaller components and discussing trade-offs of each decision. Verbalization of reasoning is the most important factor in all formats.' } },
      { title: { pt: 'Erros comuns e interpretações equivocadas', en: 'Common mistakes and misconceptions' }, content: { pt: 'O erro mais devastador é ficar em silêncio enquanto pensa. O entrevistador não pode avaliar seu raciocínio se não pode ouvi-lo. Mesmo que você não saiba a resposta, verbalizar o que está considerando, quais alternativas descartou e por que demonstra processo mental valioso. Outro erro é decorar respostas — entrevistadores experientes detectam respostas memorizadas instantaneamente.\n\nTambém é equivocado tratar perguntas comportamentais como menos importantes que técnicas. "Conte sobre um conflito em equipe" ou "descreva uma situação onde você errou" são perguntas que avaliam autoconsciência e maturidade. Respostas genéricas ou a afirmação de que "nunca teve problemas" são red flags. Outro erro comum é não fazer perguntas ao entrevistador — isso sugere desinteresse ou passividade.', en: 'The most devastating error is staying silent while thinking. The interviewer cannot evaluate your reasoning if they cannot hear it. Even if you do not know the answer, verbalizing what you are considering, which alternatives you discarded and why demonstrates valuable mental process. Another error is memorizing answers — experienced interviewers detect memorized responses instantly.\n\nIt is also wrong to treat behavioral questions as less important than technical ones. "Tell about a team conflict" or "describe a situation where you made a mistake" are questions that evaluate self-awareness and maturity. Generic responses or claiming you "never had problems" are red flags. Another common error is not asking the interviewer questions — this suggests disinterest or passivity.' } },
      { title: { pt: 'Aplicação prática no mundo real', en: 'Real-world practical application' }, content: { pt: 'Na prática, a preparação para entrevistas é um processo contínuo, não um esforço pontual. Desenvolvedores que mantêm o hábito de resolver problemas regularmente, documentar seus projetos e explicar decisões técnicas estão sempre prontos para entrevistas, mesmo sem preparação específica. Essa é a diferença entre preparação reativa (estudar às pressas quando surge uma oportunidade) e preparação contínua (manter práticas profissionais que servem tanto para o trabalho quanto para entrevistas).\n\nEmpresas que contratam bem avaliam candidatos em situações realistas. O candidato que demonstra como trabalha no dia a dia — comunicando progresso, fazendo perguntas de clarificação, considerando edge cases — impressiona mais do que aquele que apenas resolve o problema tecnicamente. O processo de entrevista simula o trabalho; comporte-se como se já estivesse trabalhando.', en: 'In practice, interview preparation is a continuous process, not a one-time effort. Developers who maintain the habit of regularly solving problems, documenting their projects, and explaining technical decisions are always ready for interviews, even without specific preparation. This is the difference between reactive preparation (rushing to study when an opportunity arises) and continuous preparation (maintaining professional practices that serve both work and interviews).\n\nCompanies that hire well evaluate candidates in realistic situations. The candidate who demonstrates how they work day-to-day — communicating progress, asking clarifying questions, considering edge cases — impresses more than one who just technically solves the problem. The interview process simulates work; behave as if you are already working.' } },
      { title: { pt: 'O que isso significa para sua carreira', en: 'What this means for your career' }, content: { pt: 'A habilidade de performar em entrevistas é uma competência de carreira separada da competência técnica. Desenvolvedores excelentes podem ser péssimos em entrevistas e vice-versa. Reconhecer isso permite tratar a entrevista como uma habilidade que pode ser desenvolvida com prática deliberada. A melhora em entrevistas vem de prática: mock interviews, resolução de problemas verbalizando raciocínio, e análise de feedback.\n\nPara o iniciante, a primeira entrevista é frequentemente a pior — e isso é normal. O objetivo não é ser perfeito na primeira vez, mas melhorar a cada tentativa. Cada entrevista, mesmo as que resultam em rejeição, é uma oportunidade de aprendizado se abordada com a mentalidade correta.', en: 'The ability to perform in interviews is a career competence separate from technical competence. Excellent developers can be terrible at interviews and vice versa. Recognizing this allows treating the interview as a skill that can be developed with deliberate practice. Interview improvement comes from practice: mock interviews, problem-solving while verbalizing reasoning, and feedback analysis.\n\nFor the beginner, the first interview is often the worst — and this is normal. The goal is not to be perfect the first time, but to improve with each attempt. Each interview, even those resulting in rejection, is a learning opportunity when approached with the correct mindset.' } },
      { title: { pt: 'Conexão com a trilha', en: 'Connection with the trail' }, content: { pt: 'Este artigo conecta a construção de presença técnica (artigos anteriores do bloco) com a inserção efetiva no mercado. O próximo artigo sobre o que empresas realmente avaliam em iniciantes complementa este ao revelar os critérios do lado do empregador, fechando o Bloco 5.', en: 'This article connects technical presence building (previous block articles) with effective market insertion. The next article on what companies really evaluate in beginners complements this by revealing criteria from the employer side, closing Block 5.' } },
      { title: { pt: 'Como aprofundar ainda mais este assunto', en: 'How to go deeper on this subject' }, content: { pt: 'Pratique mock interviews com colegas ou utilize plataformas como Pramp e interviewing.io. Resolva problemas em plataformas como LeetCode e HackerRank, mas foque em entender os padrões de solução, não em decorar respostas. Grave-se explicando soluções e reveja para melhorar sua comunicação. Após cada entrevista real, anote o que foi perguntado, como respondeu e o que faria diferente.', en: 'Practice mock interviews with colleagues or use platforms like Pramp and interviewing.io. Solve problems on platforms like LeetCode and HackerRank, but focus on understanding solution patterns, not memorizing answers. Record yourself explaining solutions and review to improve your communication. After each real interview, note what was asked, how you answered, and what you would do differently.' } },
      { title: { pt: 'Conclusão estratégica', en: 'Strategic conclusion' }, content: { pt: 'A entrevista técnica é uma demonstração de processo, não de produto. O candidato que comunica bem seu raciocínio, demonstra postura profissional e mostra capacidade de aprendizado supera consistentemente aquele que apenas sabe a resposta mas não consegue explicar como chegou lá. Preparar-se para entrevistas é preparar-se para comunicar profissionalmente — uma habilidade que serve muito além do processo seletivo.', en: 'The technical interview is a process demonstration, not a product demonstration. The candidate who communicates their reasoning well, demonstrates professional posture, and shows learning ability consistently surpasses the one who just knows the answer but cannot explain how they got there. Preparing for interviews is preparing to communicate professionally — a skill that serves far beyond the selection process.' } },
    ],
  },
  {
    id: 'mt-what-companies-evaluate',
    slugPt: 'o-que-empresas-avaliam-iniciantes',
    slugEn: 'what-companies-evaluate-in-beginners',
    title: { pt: 'O Que Empresas Realmente Avaliam em Iniciantes', en: 'What Companies Really Evaluate in Beginners' },
    excerpt: { pt: 'Os critérios reais que empresas utilizam para avaliar desenvolvedores iniciantes, além de habilidades técnicas isoladas.', en: 'The real criteria companies use to evaluate beginner developers, beyond isolated technical skills.' },
    date: { pt: '19 de Fevereiro, 2026', en: 'February 19, 2026' }, publishedDate: '2026-02-19', readTime: '22 min',
    tags: { pt: ['Carreira', 'Mercado', 'Avaliação'], en: ['Career', 'Market', 'Evaluation'] },
    keywords: { pt: ['avaliação iniciantes', 'o que empresas buscam', 'primeiro emprego dev', 'critérios contratação'], en: ['beginner evaluation', 'what companies seek', 'first dev job', 'hiring criteria'] },
    sections: [
      { title: { pt: 'Introdução: O que o mercado realmente procura', en: 'Introduction: What the market really looks for' }, content: { pt: 'A desconexão entre o que iniciantes pensam que empresas avaliam e o que realmente avaliam é uma das maiores fontes de frustração na busca pelo primeiro emprego. Iniciantes acreditam que precisam dominar 15 tecnologias, ter experiência profissional e certificações impressionantes. A realidade é diferente: empresas que contratam juniores procuram potencial de crescimento, postura profissional e fundamentos sólidos, não expertise avançada.\n\nEste artigo fecha o Bloco 5 revelando o lado do empregador. Enquanto os artigos anteriores focaram em como construir presença e se preparar, este revela os critérios que gestores técnicos e recrutadores realmente utilizam ao avaliar candidatos iniciantes.', en: 'The disconnect between what beginners think companies evaluate and what they actually evaluate is one of the greatest sources of frustration in the search for the first job. Beginners believe they need to master 15 technologies, have professional experience, and impressive certifications. Reality is different: companies hiring juniors look for growth potential, professional posture, and solid fundamentals, not advanced expertise.\n\nThis article closes Block 5 by revealing the employer side. While previous articles focused on how to build presence and prepare, this reveals the criteria technical managers and recruiters actually use when evaluating beginner candidates.' } },
      { title: { pt: 'Base conceitual: A lógica de contratação para posições júnior', en: 'Conceptual foundation: The hiring logic for junior positions' }, content: { pt: 'Quando uma empresa abre uma vaga júnior, o cálculo é claro: essa pessoa precisará de investimento em treinamento e acompanhamento. O retorno desse investimento depende de quão rápido o contratado consegue se tornar produtivo e independente. Por isso, os critérios de avaliação priorizam indicadores de velocidade de aprendizado e autonomia potencial sobre conhecimento técnico acumulado.\n\nOs indicadores que gestores buscam são: capacidade de resolver problemas de forma estruturada (não necessariamente problemas complexos), proatividade na busca de informação (pesquisar antes de perguntar), comunicação clara sobre o que sabe e o que não sabe, disposição para receber feedback e ajustar comportamento, e consistência (entregar com regularidade, não em picos de inspiração). Esses indicadores predizem melhor o sucesso em uma posição júnior do que qualquer lista de tecnologias dominadas.', en: 'When a company opens a junior position, the calculation is clear: this person will need investment in training and mentoring. The return on this investment depends on how quickly the hire can become productive and independent. Therefore, evaluation criteria prioritize indicators of learning speed and potential autonomy over accumulated technical knowledge.\n\nThe indicators managers seek are: ability to solve problems in a structured way (not necessarily complex problems), proactivity in seeking information (searching before asking), clear communication about what they know and what they do not, willingness to receive feedback and adjust behavior, and consistency (delivering regularly, not in bursts of inspiration). These indicators better predict success in a junior position than any list of mastered technologies.' } },
      { title: { pt: 'Funcionamento técnico: Os filtros do processo seletivo', en: 'Technical breakdown: The selection process filters' }, content: { pt: 'O processo seletivo típico para posições júnior tem filtros progressivos. O primeiro filtro é o currículo e perfil online: presença profissional, portfólio organizado, GitHub curado. O segundo é um teste técnico inicial, geralmente simples, que avalia se o candidato tem o mínimo de competência técnica exigida. O terceiro é a entrevista técnica que avalia raciocínio e comunicação. O quarto é a entrevista cultural que avalia adequação à equipe.\n\nO que poucos candidatos percebem é que cada filtro elimina por razões diferentes. O primeiro elimina por apresentação — e é onde a maioria é eliminada por falta de portfólio ou GitHub desorganizado. O segundo elimina por competência técnica mínima. O terceiro elimina por processo mental e comunicação. O quarto por compatibilidade comportamental. Entender a lógica de cada filtro permite preparar-se estrategicamente para cada um.', en: 'The typical selection process for junior positions has progressive filters. The first filter is resume and online profile: professional presence, organized portfolio, curated GitHub. The second is an initial technical test, usually simple, evaluating if the candidate has the minimum required technical competence. The third is the technical interview evaluating reasoning and communication. The fourth is the cultural interview evaluating team fit.\n\nWhat few candidates realize is that each filter eliminates for different reasons. The first eliminates by presentation — and is where most are eliminated due to lack of portfolio or disorganized GitHub. The second eliminates by minimum technical competence. The third by mental process and communication. The fourth by behavioral compatibility. Understanding each filter\'s logic allows strategic preparation for each.' } },
      { title: { pt: 'Erros comuns e interpretações equivocadas', en: 'Common mistakes and misconceptions' }, content: { pt: 'O erro mais prejudicial é acreditar que não está pronto o suficiente. Muitos candidatos com competência real nunca se candidatam porque se comparam com requisitos inflados de vagas. Descrições de vaga são wish lists, não requisitos absolutos. Se você atende 60-70% dos requisitos, candidatar-se é razoável. Outro erro é investir tempo excessivo em certificações que o mercado não valoriza tanto quanto experiência prática demonstrada.\n\nTambém é equivocado pensar que todas as empresas avaliam da mesma forma. Startups priorizam velocidade de aprendizado e proatividade. Corporações priorizam processo e compliance. Consultorias priorizam adaptabilidade e comunicação. Conhecer o tipo de empresa que você está abordando permite ajustar sua apresentação. Outro erro comum é não negociar ou perguntar sobre expectativas — empresas respeitam candidatos que fazem perguntas inteligentes sobre a posição.', en: 'The most harmful error is believing you are not ready enough. Many candidates with real competence never apply because they compare themselves with inflated job requirements. Job descriptions are wish lists, not absolute requirements. If you meet 60-70% of requirements, applying is reasonable. Another error is investing excessive time in certifications that the market does not value as much as demonstrated practical experience.\n\nIt is also wrong to think all companies evaluate the same way. Startups prioritize learning speed and proactivity. Corporations prioritize process and compliance. Consulting firms prioritize adaptability and communication. Knowing the type of company you are approaching allows adjusting your presentation. Another common error is not negotiating or asking about expectations — companies respect candidates who ask intelligent questions about the position.' } },
      { title: { pt: 'Aplicação prática no mundo real', en: 'Real-world practical application' }, content: { pt: 'No ambiente real de contratação, gestores técnicos frequentemente compartilham as mesmas observações: "prefiro alguém que demonstra processo profissional com tecnologias básicas do que alguém que lista 20 tecnologias no currículo mas não consegue explicar como usou nenhuma delas." A demonstração de processo — como você pensa, como se organiza, como comunica — é o indicador mais forte de sucesso em posições iniciais.\n\nIsso se manifesta em detalhes: o candidato que chega na entrevista tendo pesquisado sobre a empresa demonstra interesse genuíno. O que traz perguntas específicas sobre o time e a stack demonstra maturidade. O que admite o que não sabe mas explica como aprenderia demonstra honestidade e autonomia. Essas posturas são mais memoráveis do que respostas técnicas corretas.', en: 'In the real hiring environment, technical managers frequently share the same observations: "I prefer someone who demonstrates professional process with basic technologies over someone who lists 20 technologies on their resume but cannot explain how they used any of them." Process demonstration — how you think, how you organize, how you communicate — is the strongest indicator of success in initial positions.\n\nThis manifests in details: the candidate who arrives at the interview having researched the company demonstrates genuine interest. The one who brings specific questions about the team and stack demonstrates maturity. The one who admits what they do not know but explains how they would learn demonstrates honesty and autonomy. These postures are more memorable than correct technical answers.' } },
      { title: { pt: 'O que isso significa para sua carreira', en: 'What this means for your career' }, content: { pt: 'Entender o que empresas realmente avaliam libera o iniciante da ansiedade de "não saber o suficiente". Se o foco muda de acumular tecnologias para demonstrar processo profissional, a preparação se torna mais direcionada e eficiente. Em vez de estudar 5 frameworks superficialmente, domine 1 profundamente e demonstre como aplica pensamento profissional ao usá-lo.\n\nEssa compreensão também redefine o que significa "estar pronto" para o mercado. Você está pronto quando consegue resolver problemas de forma estruturada, comunicar seu raciocínio com clareza e demonstrar postura profissional. O conhecimento técnico específico que falta será adquirido no trabalho — e empregadores sensatos sabem disso. O que não pode ser ensinado facilmente é postura, e é isso que o processo seletivo prioriza.', en: 'Understanding what companies really evaluate frees the beginner from the anxiety of "not knowing enough." If focus shifts from accumulating technologies to demonstrating professional process, preparation becomes more directed and efficient. Instead of studying 5 frameworks superficially, master 1 deeply and demonstrate how you apply professional thinking when using it.\n\nThis understanding also redefines what "being ready" for the market means. You are ready when you can solve problems structuredly, communicate your reasoning clearly, and demonstrate professional posture. The specific technical knowledge that is missing will be acquired on the job — and sensible employers know this. What cannot be easily taught is posture, and that is what the selection process prioritizes.' } },
      { title: { pt: 'Conexão com a trilha', en: 'Connection with the trail' }, content: { pt: 'Este artigo fecha o Bloco 5, completando o ciclo de inserção no mercado. O Bloco 6 aborda armadilhas e erros estratégicos que comprometem a progressão na carreira, complementando a preparação com consciência dos riscos mais comuns.', en: 'This article closes Block 5, completing the market insertion cycle. Block 6 covers traps and strategic errors that compromise career progression, complementing preparation with awareness of the most common risks.' } },
      { title: { pt: 'Como aprofundar ainda mais este assunto', en: 'How to go deeper on this subject' }, content: { pt: 'Converse com recrutadores e gestores técnicos sobre o que realmente procuram em candidatos júnior. Participe de comunidades onde profissionais de RH e tech leads compartilham experiências de contratação. Leia relatos de pessoas que foram contratadas recentemente e note os padrões que se repetem. Analise descrições de vagas criticamente: identifique os requisitos essenciais versus os desejáveis e foque sua preparação nos essenciais.', en: 'Talk to recruiters and technical managers about what they really look for in junior candidates. Join communities where HR professionals and tech leads share hiring experiences. Read accounts from people recently hired and note repeating patterns. Analyze job descriptions critically: identify essential versus desirable requirements and focus your preparation on essentials.' } },
      { title: { pt: 'Conclusão estratégica', en: 'Strategic conclusion' }, content: { pt: 'Empresas contratam potencial, não perfeição. O candidato que demonstra fundamentos sólidos, postura profissional e capacidade de crescimento supera consistentemente aquele que tem mais conhecimento técnico mas menos maturidade comportamental. Alinhar sua preparação com o que o mercado realmente avalia é a diferença entre buscar emprego e construir carreira. O investimento em processo profissional rende dividendos que vão muito além da primeira contratação.', en: 'Companies hire potential, not perfection. The candidate who demonstrates solid fundamentals, professional posture, and growth capacity consistently surpasses the one with more technical knowledge but less behavioral maturity. Aligning your preparation with what the market actually evaluates is the difference between job hunting and career building. Investment in professional process yields dividends that go far beyond the first hire.' } },
    ],
  },
  {
    id: 'mt-linkedin-professional-profile',
    slugPt: 'perfil-profissional-linkedin',
    slugEn: 'professional-linkedin-profile',
    title: { pt: 'Como Ter um Perfil Profissional no LinkedIn (E Usar da Forma Certa Como Desenvolvedor)', en: 'How to Have a Professional LinkedIn Profile (And Use It Right as a Developer)' },
    excerpt: { pt: 'Guia estratégico sobre como estruturar um perfil profissional no LinkedIn, posicionar-se no mercado e construir reputação de longo prazo como desenvolvedor.', en: 'Strategic guide on how to structure a professional LinkedIn profile, position yourself in the market, and build long-term reputation as a developer.' },
    date: { pt: '23 de Fevereiro, 2026', en: 'February 23, 2026' }, publishedDate: '2026-02-23', readTime: '24 min',
    tags: { pt: ['LinkedIn', 'Carreira', 'Posicionamento'], en: ['LinkedIn', 'Career', 'Positioning'] },
    keywords: { pt: ['linkedin desenvolvedor', 'perfil profissional', 'posicionamento linkedin', 'reputação profissional'], en: ['linkedin developer', 'professional profile', 'linkedin positioning', 'professional reputation'] },
    sections: [
      { title: { pt: 'Introdução: LinkedIn como ferramenta de posicionamento, não de vaidade', en: 'Introduction: LinkedIn as a positioning tool, not vanity' }, content: { pt: 'O LinkedIn é a plataforma profissional mais utilizada no mundo, mas a maioria dos desenvolvedores a usa de forma ineficiente ou simplesmente a ignora. Alguns tratam como um currículo online estático. Outros reproduzem padrões de redes sociais: posts vagos, engajamento artificial, métricas de vaidade. Ambos os extremos desperdiçam o potencial real da plataforma, que é servir como ferramenta de posicionamento profissional de longo prazo.\n\nEste artigo faz parte do Bloco 5, dedicado à construção de presença profissional. Os artigos anteriores abordaram portfólio, projetos, GitHub e preparação para entrevistas. O LinkedIn complementa esse ecossistema ao fornecer um espaço onde todo esse trabalho pode ser contextualizado e apresentado para um público profissional amplo. Não se trata de "parecer profissional" — se trata de comunicar valor de forma clara e verificável.', en: 'LinkedIn is the most used professional platform in the world, but most developers use it inefficiently or simply ignore it. Some treat it as a static online resume. Others reproduce social media patterns: vague posts, artificial engagement, vanity metrics. Both extremes waste the platform\'s real potential, which is serving as a long-term professional positioning tool.\n\nThis article is part of Block 5, dedicated to building professional presence. Previous articles covered portfolio, projects, GitHub, and interview preparation. LinkedIn complements this ecosystem by providing a space where all that work can be contextualized and presented to a broad professional audience. It is not about "looking professional" — it is about communicating value clearly and verifiably.' } },
      { title: { pt: 'Como construir uma headline estratégica', en: 'How to build a strategic headline' }, content: { pt: 'A headline é o elemento mais visível do perfil — aparece em buscas, comentários, convites de conexão e recomendações. A maioria dos desenvolvedores usa headlines genéricas como "Desenvolvedor Full Stack" ou "Apaixonado por tecnologia". Essas headlines não comunicam nada de valor porque são idênticas às de milhares de outros perfis.\n\nUma headline estratégica comunica o que você faz, para quem e qual valor entrega. Em vez de "Desenvolvedor Frontend", considere "Desenvolvedor Frontend especializado em interfaces acessíveis e performance web". Em vez de "Estudante de programação", considere "Desenvolvedor em formação com foco em aplicações web e fundamentos sólidos de arquitetura". A headline deve ser específica o suficiente para atrair o público certo e profissional o suficiente para ser levada a sério. Evite emojis excessivos, buzzwords sem substância e declarações que não pode verificar. A clareza supera a criatividade.', en: 'The headline is the most visible profile element — it appears in searches, comments, connection invitations, and recommendations. Most developers use generic headlines like "Full Stack Developer" or "Passionate about technology". These headlines communicate no value because they are identical to thousands of other profiles.\n\nA strategic headline communicates what you do, for whom, and what value you deliver. Instead of "Frontend Developer", consider "Frontend Developer specializing in accessible interfaces and web performance". Instead of "Programming student", consider "Developer in training focused on web applications and solid architecture fundamentals". The headline should be specific enough to attract the right audience and professional enough to be taken seriously. Avoid excessive emojis, unsubstantiated buzzwords, and claims you cannot verify. Clarity surpasses creativity.' } },
      { title: { pt: 'Como escrever um resumo com clareza técnica', en: 'How to write a summary with technical clarity' }, content: { pt: 'A seção "Sobre" é o espaço para contextualizar sua trajetória e comunicar sua proposta profissional. A maioria dos desenvolvedores ignora essa seção ou preenche com frases genéricas. Um resumo eficaz tem três elementos: contexto (de onde você vem e o que te trouxe até aqui), competência (o que sabe fazer e com que ferramentas) e direção (para onde está indo e que tipo de desafio busca).\n\nEscreva em primeira pessoa, com tom profissional e direto. Evite superlativos vazios ("sou extremamente dedicado") e promessas genéricas ("busco contribuir com minha equipe"). Em vez disso, seja específico: mencione tecnologias com as quais tem experiência real, tipos de projetos que já construiu e problemas que sabe resolver. Inclua links para portfólio e GitHub. O resumo deve funcionar como um elevator pitch escrito — em 30 segundos de leitura, o visitante deve entender quem você é profissionalmente e o que pode oferecer.', en: 'The "About" section is the space to contextualize your trajectory and communicate your professional proposition. Most developers ignore this section or fill it with generic phrases. An effective summary has three elements: context (where you come from and what brought you here), competence (what you know how to do and with what tools), and direction (where you are going and what type of challenge you seek).\n\nWrite in first person, with professional and direct tone. Avoid empty superlatives ("I am extremely dedicated") and generic promises ("I seek to contribute to my team"). Instead, be specific: mention technologies with which you have real experience, types of projects you have built, and problems you know how to solve. Include links to portfolio and GitHub. The summary should function as a written elevator pitch — in 30 seconds of reading, the visitor should understand who you are professionally and what you can offer.' } },
      { title: { pt: 'Erros comuns que iniciantes cometem no LinkedIn', en: 'Common mistakes beginners make on LinkedIn' }, content: { pt: 'O erro mais frequente é perfil incompleto: sem foto profissional, sem headline personalizada, sem resumo, sem projetos listados. Um perfil incompleto comunica que você não leva sua presença profissional a sério. Outro erro é conectar-se com centenas de pessoas sem critério e sem interação — rede profissional se constrói com relevância, não volume.\n\nTambém é equivocado postar conteúdo motivacional genérico ou compartilhar posts virais sem adicionar perspectiva própria. Isso não constrói reputação técnica — constrói a imagem de alguém que busca atenção. Outro erro comum é não atualizar o perfil regularmente. Se você aprendeu uma nova tecnologia, completou um projeto ou assumiu uma nova responsabilidade, o perfil deve refletir isso. Perfis desatualizados perdem relevância nas buscas e passam impressão de estagnação.\n\nPor fim, evitar o LinkedIn completamente é um erro estratégico. Mesmo que você não goste da plataforma, recrutadores a usam ativamente. Não estar presente significa perder oportunidades que nunca saberá que existiram. O perfil não precisa ser ativo diariamente — precisa estar completo, atualizado e profissional.', en: 'The most frequent error is an incomplete profile: no professional photo, no customized headline, no summary, no listed projects. An incomplete profile communicates you do not take your professional presence seriously. Another mistake is connecting with hundreds of people without criteria and without interaction — professional networks are built with relevance, not volume.\n\nIt is also wrong to post generic motivational content or share viral posts without adding your own perspective. This does not build technical reputation — it builds the image of someone seeking attention. Another common mistake is not updating the profile regularly. If you learned a new technology, completed a project, or assumed a new responsibility, the profile should reflect this. Outdated profiles lose relevance in searches and give an impression of stagnation.\n\nFinally, completely avoiding LinkedIn is a strategic error. Even if you do not like the platform, recruiters actively use it. Not being present means losing opportunities you will never know existed. The profile does not need to be active daily — it needs to be complete, updated, and professional.' } },
      { title: { pt: 'Aplicação prática: conectando GitHub, portfólio e presença técnica', en: 'Practical application: connecting GitHub, portfolio and technical presence' }, content: { pt: 'O LinkedIn alcança seu potencial máximo quando está conectado ao seu ecossistema profissional. Adicione o link do seu portfólio na seção de informações de contato e no resumo. Liste seus melhores projetos na seção "Em destaque" com screenshots e links para o código. Vincule sua conta GitHub ao perfil. Quando postar conteúdo técnico, referencie projetos reais que você construiu.\n\nIsso cria um ciclo virtuoso: o LinkedIn direciona tráfego para seu portfólio e GitHub; o portfólio e GitHub validam o que está escrito no LinkedIn. Recrutadores que encontram consistência entre todas as plataformas desenvolvem confiança no candidato. Inconsistências — como listar tecnologias no LinkedIn que não aparecem em nenhum projeto — geram desconfiança. A coerência entre todas as plataformas é um sinal forte de profissionalismo.', en: 'LinkedIn reaches its maximum potential when connected to your professional ecosystem. Add your portfolio link in the contact information section and summary. List your best projects in the "Featured" section with screenshots and code links. Link your GitHub account to the profile. When posting technical content, reference real projects you built.\n\nThis creates a virtuous cycle: LinkedIn directs traffic to your portfolio and GitHub; the portfolio and GitHub validate what is written on LinkedIn. Recruiters who find consistency across all platforms develop trust in the candidate. Inconsistencies — like listing technologies on LinkedIn that do not appear in any project — generate distrust. Coherence across all platforms is a strong signal of professionalism.' } },
      { title: { pt: 'Como postar conteúdo técnico com maturidade', en: 'How to post technical content with maturity' }, content: { pt: 'Conteúdo técnico no LinkedIn funciona quando é genuíno, específico e útil. Compartilhe aprendizados reais de projetos que construiu: problemas que enfrentou, como resolveu, o que aprendeu. Escreva análises breves sobre tecnologias que experimentou. Comente sobre decisões técnicas de projetos open source que admira. Esse tipo de conteúdo demonstra profundidade e posiciona você como alguém que pensa criticamente sobre tecnologia.\n\nEvite posts que buscam engajamento artificial: "concordam?", listas óbvias, reposts sem contexto. Evite também debates polêmicos sobre tecnologias ("framework X é melhor que Y") sem fundamentação técnica sólida. A frequência ideal é consistência moderada: 1-2 posts por semana com qualidade é mais eficaz do que posts diários sem substância. O objetivo não é viralizar — é construir reputação. Reputação se constrói com consistência e qualidade ao longo de meses e anos, não com picos de visibilidade seguidos de silêncio.', en: 'Technical content on LinkedIn works when it is genuine, specific, and useful. Share real learnings from projects you built: problems you faced, how you solved them, what you learned. Write brief analyses about technologies you experimented with. Comment on technical decisions of open source projects you admire. This type of content demonstrates depth and positions you as someone who thinks critically about technology.\n\nAvoid posts seeking artificial engagement: "agree?", obvious lists, reposts without context. Also avoid controversial technology debates ("framework X is better than Y") without solid technical foundation. The ideal frequency is moderate consistency: 1-2 quality posts per week is more effective than daily posts without substance. The goal is not to go viral — it is to build reputation. Reputation is built with consistency and quality over months and years, not with visibility spikes followed by silence.' } },
      { title: { pt: 'Conexão com a trilha', en: 'Connection with the trail' }, content: { pt: 'Este artigo complementa o Bloco 5 ao adicionar mais uma dimensão à presença profissional. Enquanto portfólio e GitHub demonstram competência técnica diretamente, o LinkedIn contextualiza essa competência em um perfil profissional completo. Os artigos sobre entrevistas e avaliação de empresas são diretamente beneficiados por um perfil LinkedIn forte, que frequentemente é o primeiro ponto de contato no processo seletivo.', en: 'This article complements Block 5 by adding another dimension to professional presence. While portfolio and GitHub directly demonstrate technical competence, LinkedIn contextualizes that competence in a complete professional profile. The articles on interviews and company evaluation are directly benefited by a strong LinkedIn profile, which is often the first contact point in the selection process.' } },
      { title: { pt: 'Como aprofundar ainda mais este assunto', en: 'How to go deeper on this subject' }, content: { pt: 'Analise perfis de desenvolvedores que ocupam posições que você almeja. Note como estruturam headlines, resumos e experiências. Observe o tipo de conteúdo que postam e como interagem com outros profissionais. Use o LinkedIn Learning para desenvolver competências complementares. Participe de grupos técnicos relevantes e contribua com perspectivas fundamentadas. Peça recomendações a colegas com quem trabalhou e ofereça as suas em retorno — recomendações reais de pessoas reais validam competências de forma que autodeclarações não conseguem.', en: 'Analyze profiles of developers who hold positions you aspire to. Note how they structure headlines, summaries, and experiences. Observe the type of content they post and how they interact with other professionals. Use LinkedIn Learning to develop complementary skills. Join relevant technical groups and contribute with well-founded perspectives. Ask recommendations from colleagues you worked with and offer yours in return — real recommendations from real people validate competencies in ways self-declarations cannot.' } },
      { title: { pt: 'Conclusão estratégica', en: 'Strategic conclusion' }, content: { pt: 'O LinkedIn não é uma rede social — é uma ferramenta de posicionamento profissional. Tratá-lo com a mesma seriedade que você trata seu código e seus projetos gera retornos mensuráveis em oportunidades de carreira. Um perfil completo, consistente com seu portfólio e GitHub, alimentado com conteúdo técnico genuíno, posiciona você como um profissional sério em um mercado saturado de perfis genéricos. A construção de reputação profissional é um investimento de longo prazo que começa com decisões simples, aplicadas com consistência.', en: 'LinkedIn is not a social network — it is a professional positioning tool. Treating it with the same seriousness you treat your code and projects generates measurable returns in career opportunities. A complete profile, consistent with your portfolio and GitHub, fed with genuine technical content, positions you as a serious professional in a market saturated with generic profiles. Building professional reputation is a long-term investment that starts with simple decisions, applied consistently.' } },
    ],
  },
];
